import assert from 'node:assert/strict';
import test from 'node:test';

import { calculateBuilderIndex, finalizeSnapshot, logarithmicScore } from '../scripts/lib/model.mjs';

const rawSnapshot = {
  profile: {
    login: 'rohitg00',
    name: 'Rohit Ghumare',
    followers: 6000,
    originalRepositoryCount: 100,
  },
  metrics: {
    ownedStars: 95000,
    commits: 600,
    pullRequests: 150,
    issues: 80,
    reviews: 200,
    windowDays: 365,
  },
  ranking: {
    followerWorld: { position: 700 },
    topProjectWorld: { position: 120 },
  },
  topRepositories: [],
};

test('logarithmic scoring is bounded and monotonic', () => {
  assert.equal(logarithmicScore(0, 100), 0);
  assert.ok(logarithmicScore(50, 100) < logarithmicScore(100, 100));
  assert.equal(logarithmicScore(1000, 100), 100);
});

test('Builder Index is transparent, bounded, and does not invent a global rank', () => {
  const index = calculateBuilderIndex(rawSnapshot);

  assert.ok(index.score > 0 && index.score <= 100);
  assert.equal(index.globalRank, null);
  assert.equal(index.model.version, '1.0.0');
  assert.deepEqual(Object.keys(index.values), [
    'creation',
    'shipping',
    'collaboration',
    'maintenance',
    'community',
  ]);
});

test('unchanged public data preserves its generation timestamp', () => {
  const first = finalizeSnapshot(rawSnapshot, null, new Date('2026-08-24T10:00:00Z'));
  const second = finalizeSnapshot(rawSnapshot, first, new Date('2026-08-24T11:00:00Z'));

  assert.equal(second.fingerprint, first.fingerprint);
  assert.equal(second.generatedAt, first.generatedAt);
});

test('creator measurement timestamps are retained without changing the content fingerprint', () => {
  const creator = {
    position: 80, rankedProfiles: '1.6M', topPercent: .01, monthlyChange: 14,
    stars: 103211, status: 'fresh', source: 'https://gitranks.com/profile/rohitg00/ranks',
    measuredAt: '2026-09-25T13:00:00Z',
  };
  const raw = { ...rawSnapshot, ranking: { ...rawSnapshot.ranking, gitRanksCreator: creator } };
  const first = finalizeSnapshot(raw, null, new Date('2026-09-25T13:00:00Z'));
  const refreshedCreator = { ...creator, measuredAt: '2026-09-25T13:30:00Z' };
  const refreshed = { ...raw, ranking: { ...raw.ranking, gitRanksCreator: refreshedCreator } };
  const before = structuredClone(refreshed);
  const second = finalizeSnapshot(refreshed, first, new Date('2026-09-25T13:30:00Z'));

  assert.equal(second.fingerprint, first.fingerprint);
  assert.equal(second.generatedAt, first.generatedAt);
  assert.deepEqual(second.ranking.gitRanksCreator, refreshedCreator);
  assert.deepEqual(refreshed, before);
  assert.deepEqual(first.ranking.gitRanksCreator, creator);

  for (const change of [
    { position: 79 }, { rankedProfiles: '1.7M' }, { topPercent: .02 }, { monthlyChange: 15 },
    { stars: 103212 }, { status: 'cached' }, { source: 'https://gitranks.com/new-source' },
  ]) {
    const changed = finalizeSnapshot({ ...raw, ranking: { ...raw.ranking, gitRanksCreator: { ...creator, ...change } } }, first);
    assert.notEqual(changed.fingerprint, first.fingerprint);
  }
  const otherMeasurement = finalizeSnapshot({ ...raw, measuredAt: creator.measuredAt }, first);
  assert.notEqual(otherMeasurement.fingerprint, first.fingerprint);
});

test('country measurement dates do not cause content changes but ranks and cached scores do', () => {
  const benchmark = { status: 'fresh', measuredAt: '2026-09-25T00:00:00Z', measuredValue: 95000, positions: { india: { label: 'India', position: 1 } } };
  const raw = { ...rawSnapshot, ranking: { ...rawSnapshot.ranking, creatorBenchmarks: benchmark } };
  const first = finalizeSnapshot(raw, null);
  const refreshed = { ...benchmark, measuredAt: '2026-09-26T00:00:00Z' };
  const second = finalizeSnapshot({ ...raw, ranking: { ...raw.ranking, creatorBenchmarks: refreshed } }, first);
  assert.equal(first.fingerprint, second.fingerprint);
  assert.equal(first.generatedAt, second.generatedAt);
  assert.deepEqual(second.ranking.creatorBenchmarks, refreshed);
  assert.equal(benchmark.measuredAt, '2026-09-25T00:00:00Z');
  for (const change of [{ status: 'cached' }, { measuredValue: 98000 }, { positions: { india: { label: 'India', position: 2 } } }]) {
    const changed = finalizeSnapshot({ ...raw, ranking: { ...raw.ranking, creatorBenchmarks: { ...benchmark, ...change } } }, first);
    assert.notEqual(changed.fingerprint, first.fingerprint);
  }
});

{
  "name": "rohitg00-profile-rank",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "update": "node scripts/update-profile.mjs",
    "render": "node scripts/render-profile.mjs",
    "test": "node --test",
    "verify": "npm test && npm run render"
  },
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "opentype.js": "^2.0.0"
  }
}

import { createHash } from 'node:crypto';

export const BUILDER_INDEX_MODEL = {
  version: '1.0.0',
  components: {
    creation: { weight: 0.35, cap: 100_000 },
    shipping: { weight: 0.25, cap: 1_000 },
    collaboration: { weight: 0.2, pullRequestCap: 250, reviewCap: 500 },
    maintenance: { weight: 0.1, cap: 250 },
    community: { weight: 0.1, cap: 10_000 },
  },
};

export function logarithmicScore(value, cap) {
  if (!Number.isFinite(value) || value <= 0) {
    return 0;
  }
  return Math.min(100, (Math.log1p(value) / Math.log1p(cap)) * 100);
}

function round(value, digits = 1) {
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
}

export function calculateBuilderIndex(snapshot) {
  const { components } = BUILDER_INDEX_MODEL;
  const creation = logarithmicScore(snapshot.metrics.ownedStars, components.creation.cap);
  const shipping = logarithmicScore(snapshot.metrics.commits, components.shipping.cap);
  const collaboration =
    logarithmicScore(snapshot.metrics.pullRequests, components.collaboration.pullRequestCap) * 0.65 +
    logarithmicScore(snapshot.metrics.reviews, components.collaboration.reviewCap) * 0.35;
  const maintenance = logarithmicScore(snapshot.metrics.issues, components.maintenance.cap);
  const community = logarithmicScore(snapshot.profile.followers, components.community.cap);

  const values = {
    creation: round(creation),
    shipping: round(shipping),
    collaboration: round(collaboration),
    maintenance: round(maintenance),
    community: round(community),
  };

  const score = Object.entries(values).reduce(
    (total, [name, value]) => total + value * components[name].weight,
    0,
  );

  return {
    score: round(score),
    scale: 100,
    values,
    model: BUILDER_INDEX_MODEL,
    classification: classifyBuilder(score),
    globalRank: null,
    globalRankStatus: 'A reproducible comparison corpus is required before this score can claim a world rank.',
  };
}

function classifyBuilder(score) {
  if (score >= 90) return 'Public ecosystem builder';
  if (score >= 75) return 'Open source builder';
  if (score >= 55) return 'Active maintainer';
  if (score >= 35) return 'Active contributor';
  return 'Emerging builder';
}

function stableValue(value) {
  if (Array.isArray(value)) {
    return value.map(stableValue);
  }
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value)
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([key, child]) => [key, stableValue(child)]),
    );
  }
  return value;
}

export function fingerprint(value) {
  return createHash('sha256').update(JSON.stringify(stableValue(value))).digest('hex');
}

export function finalizeSnapshot(rawSnapshot, previousSnapshot, now = new Date()) {
  const candidate = {
    schemaVersion: 1,
    ...rawSnapshot,
    builderIndex: calculateBuilderIndex(rawSnapshot),
    privacy: {
      visibility: 'public-only',
      privateRepositoriesIncluded: false,
      restrictedContributionTotalsIncluded: false,
      titlesAndCommitMessagesIncluded: false,
      policy: 'Every contribution row must belong to a repository whose GitHub visibility is PUBLIC.',
    },
  };
  const fingerprintCandidate = structuredClone(candidate);
  delete fingerprintCandidate.ranking?.gitRanksCreator?.measuredAt;
  delete fingerprintCandidate.ranking?.creatorBenchmarks?.measuredAt;
  const contentFingerprint = fingerprint(fingerprintCandidate);
  const unchanged = previousSnapshot?.fingerprint === contentFingerprint;

  return {
    ...candidate,
    fingerprint: contentFingerprint,
    generatedAt: unchanged ? previousSnapshot.generatedAt : now.toISOString(),
  };
}

import assert from 'node:assert/strict';
import { EventEmitter } from 'node:events';
import test from 'node:test';
import { githubApi } from '../scripts/lib/github-cli.mjs';

test('GitHub CLI sends GraphQL variables through stdin and keeps credentials out of argv', async () => {
  const body = { query: 'query($after: String) { viewer { login } }', variables: { after: null } };
  const result = await githubApi('graphql', 'test-secret', body, (binary, args, options, callback) => {
    assert.equal(binary, 'gh');
    assert.deepEqual(args.slice(-2), ['--input', '-']);
    assert.equal(args.includes('test-secret'), false);
    assert.equal(options.env.GH_TOKEN, 'test-secret');
    assert.equal(options.env.GH_DEBUG, '');
    const stdin = new EventEmitter();
    stdin.end = value => {
      assert.deepEqual(JSON.parse(value), body);
      callback(null, '{"data":{"viewer":{"login":"rohitg00"}}}');
    };
    return { stdin };
  });
  assert.equal(result.data.viewer.login, 'rohitg00');
});

test('failed CLI requests do not expose raw stderr or credentials', async () => {
  await assert.rejects(githubApi('/users/rohitg00', 'test-secret', null, (binary, args, options, callback) => {
    assert.equal(args[args.indexOf('--method') + 1], 'GET');
    const stdin = new EventEmitter();
    stdin.end = () => callback(Object.assign(new Error('test-secret'), { code: 1 }));
    return { stdin };
  }), error => /GitHub CLI request failed/.test(error.message) && !error.message.includes('test-secret'));
});

import assert from 'node:assert/strict';
import test from 'node:test';

import { finalizeSnapshot } from '../scripts/lib/model.mjs';
import { updateHistory } from '../scripts/update-profile.mjs';

function snapshot(at, scoreInput = 100) {
  return finalizeSnapshot(
    {
      profile: { login: 'rohitg00', followers: scoreInput, originalRepositoryCount: 1 },
      metrics: {
        ownedStars: scoreInput,
        commits: scoreInput,
        pullRequests: scoreInput,
        issues: scoreInput,
        reviews: scoreInput,
        windowDays: 365,
      },
      ranking: {
        followerWorld: { position: 100 },
        topProjectWorld: { position: 100 },
      },
      topRepositories: [],
    },
    null,
    new Date(at),
  );
}

test('history keeps one current entry per day and skips unchanged refreshes', () => {
  const first = snapshot('2026-08-24T10:00:00Z');
  const firstHistory = updateHistory([], first, true);
  const unchangedHistory = updateHistory(firstHistory, first, false);
  const changedSameDay = updateHistory(firstHistory, snapshot('2026-08-24T14:00:00Z', 150), true);

  assert.equal(firstHistory.length, 1);
  assert.deepEqual(unchangedHistory, firstHistory);
  assert.equal(changedSameDay.length, 1);
  assert.notEqual(changedSameDay[0].builderIndex, firstHistory[0].builderIndex);
});

import assert from 'node:assert/strict';
import test from 'node:test';

import { THEMES } from '../scripts/lib/theme.mjs';

function luminance(hex) {
  const channels = hex.slice(1).match(/../g).map(value => parseInt(value, 16) / 255)
    .map(value => value <= .04045 ? value / 12.92 : ((value + .055) / 1.055) ** 2.4);
  return channels[0] * .2126 + channels[1] * .7152 + channels[2] * .0722;
}

test('body, accent and diff text meet 4.5:1 contrast against each theme background', () => {
  for (const [name, theme] of Object.entries(THEMES)) {
    const background = luminance(theme.paper);
    for (const key of ['ink', 'blue', 'positive', 'negative']) {
      const foreground = luminance(theme[key]);
      const contrast = (Math.max(foreground, background) + .05) / (Math.min(foreground, background) + .05);
      assert.ok(contrast >= 4.5, `${name} ${key}: ${contrast.toFixed(2)}:1`);
    }
  }
});

import assert from 'node:assert/strict';
import test from 'node:test';

import { parseGitRanksCreator, refreshGitRanksCreator } from '../scripts/lib/gitranks.mjs';

function streamedCard({ change = '↑14', stars = '103,211', description = 'Counts stars on repositories owned by the profile.' } = {}) {
  const tree = ['$', 'div', null, { 'data-slot': 'card', children: [
    ['Position: ', '80', ['$', 'span', null, { children: ['/', ['$', '$L8', null, { href: '/by/stars/1', children: '1.6M' }]] }]],
    ['Top ', .01, '% of all ranked profiles'],
    ['$', 'span', null, { children: ['This month change: ', ['$', 'span', null, { children: change }]] }],
    ['Total ', 'star', 's: ', stars],
    description,
  ] }];
  const record = `52:${JSON.stringify(tree)}\n`;
  return `<script>self.__next_f.push(${JSON.stringify([1, record.slice(0, 100)])})</script><script>self.__next_f.push(${JSON.stringify([1, record.slice(100)])})</script>`;
}

test('GitRanks parser reads its reported creator rank, cohort, percentile, movement and stars', () => {
  const unrelated = streamedCard({ stars: '439,300', description: 'Counts stars on repos owned by others.' });
  assert.deepEqual(parseGitRanksCreator(unrelated + streamedCard()), {
    position: 80, rankedProfiles: '1.6M', topPercent: .01, monthlyChange: 14, stars: 103211,
  });
});

test('GitRanks movements retain direction and missing movements remain unknown', () => {
  assert.equal(parseGitRanksCreator(streamedCard({ change: '↓1,002' })).monthlyChange, -1002);
  assert.equal(parseGitRanksCreator(streamedCard({ change: '' })).monthlyChange, null);
});

test('malformed creator rows do not hide a subsequent valid card', () => {
  const record = '51:not JSON: Counts stars on repositories owned by the profile.\n';
  const malformed = `<script>self.__next_f.push(${JSON.stringify([1, record])})</script>`;
  assert.deepEqual(parseGitRanksCreator(malformed + streamedCard()), parseGitRanksCreator(streamedCard()));
  assert.throws(() => parseGitRanksCreator(malformed), /could not be verified/);
});

test('incomplete or unrelated rankings cannot substitute for creator data', () => {
  assert.throws(() => parseGitRanksCreator(streamedCard({ stars: '' })), /could not be verified/);
  assert.throws(() => parseGitRanksCreator(streamedCard({ description: 'Follower rank' })), /could not be verified/);
  assert.throws(() => parseGitRanksCreator('<html>Service unavailable</html>'), /could not be verified/);
});

test('failed GitRanks refresh keeps the original measurement date and reports cached or unavailable', async () => {
  const previous = { position: 80, stars: 103211, measuredAt: '2026-09-25T13:00:00Z' };
  const fail = async () => { throw new Error('Profile unavailable'); };
  const cached = await refreshGitRanksCreator('rohitg00', previous, new Date(), fail);
  assert.deepEqual(cached, { ...previous, status: 'cached' });
  const unavailable = await refreshGitRanksCreator('rohitg00', null, new Date(), fail);
  assert.equal(unavailable.status, 'unavailable');
  assert.equal(unavailable.position, undefined);
});

test('failed refreshes cannot turn missing or unverified measurements into cached rankings', async () => {
  const fail = async () => { throw new Error('Profile unavailable'); };
  for (const previous of [
    { status: 'unavailable', measuredAt: null },
    { position: null, measuredAt: '2026-09-25T13:00:00Z' },
    { position: Infinity, measuredAt: '2026-09-25T13:00:00Z' },
    { position: 0, measuredAt: '2026-09-25T13:00:00Z' },
    { position: 80, measuredAt: null },
    { position: 80, measuredAt: 'invalid' },
  ]) {
    assert.deepEqual(await refreshGitRanksCreator('rohitg00', previous, new Date(), fail), {
      status: 'unavailable', measuredAt: null,
    });
  }
});

import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

import {
  aggregateMergedContributionOrganizations,
  composeEcosystemOrganizations,
  sumPublicContributions,
  languageShares,
  recentContributionRepositories,
  summarizeRepositoryContributions,
} from '../scripts/lib/github.mjs';

const contributionFixture = JSON.parse(
  await readFile(new URL('./fixtures/contributions.json', import.meta.url), 'utf8'),
);

test('contribution totals include only explicitly public repositories', () => {
  const rows = [
    ...contributionFixture,
    { repository: { visibility: 'INTERNAL' }, contributions: { totalCount: 200 } },
    { repository: {}, contributions: { totalCount: 300 } },
    { contributions: { totalCount: 400 } },
  ];
  assert.equal(sumPublicContributions(rows), 8);
  assert.equal(sumPublicContributions(), 0);
});

test('contributed organization marks require a merged public pull request', () => {
  const organizations = aggregateMergedContributionOrganizations(
    [
      {
        mergedAt: '2025-06-11T08:57:00Z',
        repository: {
          nameWithOwner: 'microsoft/mcp-for-beginners',
          visibility: 'PUBLIC',
          url: 'https://github.com/microsoft/mcp-for-beginners',
          stargazerCount: 1000,
          owner: {
            __typename: 'Organization',
            login: 'microsoft',
            avatarUrl: 'https://avatars.example/microsoft',
            url: 'https://github.com/microsoft',
          },
        },
      },
      {
        mergedAt: '2026-08-24T10:00:00Z',
        repository: {
          nameWithOwner: 'modelcontextprotocol/registry',
          visibility: 'PUBLIC',
          url: 'https://github.com/modelcontextprotocol/registry',
          stargazerCount: 5000,
          owner: {
            __typename: 'Organization',
            login: 'modelcontextprotocol',
            avatarUrl: 'https://avatars.example/mcp',
            url: 'https://github.com/modelcontextprotocol',
          },
        },
      },
      {
        mergedAt: null,
        repository: {
          nameWithOwner: 'anthropics/anthropic-cookbook',
          visibility: 'PUBLIC',
          url: 'https://github.com/anthropics/anthropic-cookbook',
          stargazerCount: 30000,
          owner: {
            __typename: 'Organization',
            login: 'anthropics',
            avatarUrl: 'https://avatars.example/anthropic',
            url: 'https://github.com/anthropics',
          },
        },
      },
    ],
    'rohitg00',
    5,
    {
      priorityLogins: ['microsoft', 'modelcontextprotocol'],
    },
